 function templateStage(known){const name=known?.name;if(name==='1、初步业务活动工作底稿.zip')return 3;if(name==='2、计划及风险识别阶段工作底稿.zip')return 4;for(const n of [5,6,7])if(name===P.config(n)?.canonicalName)return n;if(name==='内部控制调查问卷（风险评估程序底稿）.zip')return'common-risk';if(name==='通用工作底稿.zip')return'common-general';return null;}
 function hasTemplateStage(value,phase){if(typeof phase==='number'&&P.files(value,phase).length)return true;return sourceArchives(value).some(a=>templateStage(root.WorkpaperRouting?.identifyArchive?.(a.hash))===phase);}
 async function linkLocalTemplates(value,n,isCurrent){const result={record:value,notice:'',candidates:[]};if(![2,3,4,5,6,7].includes(n)||!root.AuditTemplates?.open||!root.AuditTemplates?.applyToProject)return result;if(n!==2&&hasTemplateStage(value,n))return result;if(Object.keys(value.workpaperLocks||{}).length){result.notice='本项目已有核对冻结版本，不自动关联或改写原包；已保存原表继续只读使用。';return result;}let store;try{store=await root.AuditTemplates.open();const inventory=await store.list();if(!isCurrent())return result;const groups=new Map();for(const metadata of inventory.records){const known=root.WorkpaperRouting?.identifyArchive?.(metadata.sha256),phase=templateStage(known);if(!known||phase===null||n!==2&&phase!==n||hasTemplateStage(value,phase))continue;if(!groups.has(phase))groups.set(phase,[]);groups.get(phase).push({sha256:metadata.sha256,name:known.name,phase});}let count=0;for(const candidates of groups.values()){if(candidates.length!==1){result.candidates.push(...candidates);continue;}if(!isCurrent())return result;const chosen=candidates[0],before=await S.get(value.id);if(before.rev!==result.record.rev||Object.keys(before.workpaperLocks||{}).length)throw Error('项目在关联前已变化或冻结，未自动改写；请刷新核对');const safeStore={...S,async get(id){const r=await S.get(id);if(!isCurrent())throw Error('项目已切换，未关联旧模板');return r;},async save(id,rev,patch){if(!isCurrent())throw Error('项目已切换，未关联旧模板');if(id!==value.id||Object.keys(patch).sort().join(',')!=='workpaperSources')throw Error('模板关联范围无效');return S.save(id,rev,patch);}};result.record=await root.AuditTemplates.applyToProject({sha256:chosen.sha256,projectId:value.id,expectedRevision:result.record.rev,store,workspaceStore:safeStore});count++;}if(count)result.notice='已从基础资料的本机模板库关联 '+count+' 个准确原包，无需重复上传；已有填写与原公式、链接均保留。';if(result.candidates.length)result.notice+=(result.notice?' ':'')+'本机存在多个同阶段已注册版本，请明确选择下方现存版本，不自动猜测。';if(!groups.size&&inventory.records.length)result.notice='本机模板库暂无本阶段唯一、已注册身份的原包；未知模板不猜测套用，请到基础资料核对现存版本。';return result;}catch(e){result.notice='本机模板关联未全部完成：'+e.message+'；原包和填写保留，无需重复上传已保存到基础资料的原件。';return result;}finally{store?.close();}}
 function templateTools(container){if(!templateState?.notice&&!templateState?.candidates?.length)return;const hint=el('p',templateState.notice,'pw-original-help');container.append(hint);if(!templateState.candidates?.length)return;const picker=el('div');for(const candidate of templateState.candidates){const b=btn('使用本机版本：'+candidate.name+' · '+candidate.sha256.slice(0,12));b.dataset.localTemplate=candidate.sha256;const project=key,requestedStage=stage,expected=record.rev;b.onclick=()=>void run(async()=>{if(!guard())return;if(key!==project||stage!==requestedStage||record.rev!==expected)throw Error('项目或阶段已变化，请刷新后选择本机版本');if(Object.keys(record.workpaperLocks||{}).length)throw Error('项目已冻结，未关联其他版本');const store=await root.AuditTemplates.open();try{const next=await root.AuditTemplates.applyToProject({sha256:candidate.sha256,projectId:project,expectedRevision:expected,store});if(key!==project||stage!==requestedStage)return;record=next;templateState={record,notice:'已明确关联本机所选原包，原填写保留，无需再次上传。',candidates:[]};render();say(templateState.notice);}finally{store.close();}});picker.append(b);}container.append(picker);}
 function sourceArchives(value){return [value?.archive,value?.riskArchive,...Object.values(value?.workpaperSources||{}).map(s=>s?.archive)].filter(a=>a&&typeof a.hash==='string'&&a.blob);}
 function pendingValues(value){if(!value||value.schemaVersion!==1||!Number.isSafeInteger(value.revision)||value.revision<0||!value.changes||typeof value.changes!=='object'||Array.isArray(value.changes)||Object.keys(value).sort().join(',')!=='changes,revision,schemaVersion')throw Error('底稿暂存数据格式无效');const changes=Object.create(null);let count=0,total=0;for(const [sheet,items]of Object.entries(value.changes)){if(typeof sheet!=='string'||['__proto__','constructor','prototype'].includes(sheet)||sheet.length>300||!items||typeof items!=='object'||Array.isArray(items))throw Error('底稿暂存工作表无效');changes[sheet]=Object.create(null);for(const [id,text]of Object.entries(items)){if(['__proto__','constructor','prototype'].includes(id)||typeof text!=='string'||text.length>150000||!text.isWellFormed()||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(text)||++count>10000||(total+=text.length)>1000000)throw Error('底稿暂存字段过大或无效');changes[sheet][id]=text;}}if(!count)throw Error('暂存没有未提交的底稿填写');return changes;}
